return {["Sheet1"]={["1"]={["id"]=1,["text"]=[[江湖小报：放置江湖本意虽是放置游戏，但无法阻挡肝帝玩家。]]},["10"]={["id"]=10,["text"]=[[江湖小报：每周在酆都玩法中获取的冥币有一定上限。]]},["11"]={["id"]=11,["text"]=[[江湖小报：主动技能传承是不保留的，但会根据提升的熟练度折算成门派贡献值返到传承后的门派。]]},["12"]={["id"]=12,["text"]=[[江湖小报：传承时，官职头衔以及政绩全部清空。]]},["13"]={["id"]=13,["text"]=[[江湖小报：传承时，经脉等级以及真气值完全清空。]]},["14"]={["id"]=14,["text"]=[[江湖小报：传承时，经脉加成的属性会伴随经脉清空而清空。]]},["15"]={["id"]=15,["text"]=[[江湖小报：传承时，潜能值全部清空。而经验值超过传承要求的部分会折算成传人的潜能。]]},["16"]={["id"]=16,["text"]=[[江湖小报：听说制作组彩蛋玩法内里有策划，还有技术。]]},["17"]={["id"]=17,["text"]=[[江湖小报：如烟真的是个小姐姐，我怎么知道？那是个甜蜜的夜晚。。]]},["18"]={["id"]=18,["text"]=[[江湖小报：传承时，门派贡献值全部清零。可以在传承前多买一些主动招式残页，传承后再出售。]]},["19"]={["id"]=19,["text"]=[[江湖小报：传承时，角色的冥币、容貌、碎银、黄金以及使用醉梦生获得的精力上限均会被保留。]]},["2"]={["id"]=2,["text"]=[[江湖小报：虽说一名剑客最重要的便是手中的剑，但江湖险恶，恐要多掌握一些拳脚武学防身。]]},["20"]={["id"]=20,["text"]=[[江湖小报：传承时，角色的装饰箱内物品、江湖武学书页以及主动招式残页均会被保留。]]},["21"]={["id"]=21,["text"]=[[江湖小报：传承时，角色的包月分身符、江湖名士身份以及江湖名士奖励未领取累计天数均会被保留。]]},["22"]={["id"]=22,["text"]=[[江湖小报：传承时，读书识字保留一半的经验值，背包内书籍保留但等级变成1级。]]},["23"]={["id"]=23,["text"]=[[江湖小报：传承时，所学江湖秘籍武学不保留，传承后通关三十五章可找上一代继承武学与一半经验值。]]},["24"]={["id"]=24,["text"]=[[江湖小报：传承时，角色掌握的长生诀和灵照经均会被完整保留。]]},["25"]={["id"]=25,["text"]=[[江湖小报：传承时，角色掌握的五行遁法、易容术以及走穴十四经会被保留，但只保留一半经验。]]},["26"]={["id"]=26,["text"]=[[江湖小报：重置角色只保留剩余元宝，江湖名士剩余天数，购买的关卡，其他数据都伴随角色一并抹除。]]},["27"]={["id"]=27,["text"]=[[江湖小报：论剑玩法中除了自身的实力，计谋的选择也是重要的一环，熟练掌握计谋会让你事半功倍。]]},["28"]={["id"]=28,["text"]=[[江湖小报：嵩山宗的韩一枫，他的身世十分离奇，远非普通人能够想象。]]},["29"]={["id"]=29,["text"]=[[江湖小报：作为酷跑达人柳玄风，不知少侠可有和他切磋，关于轻功的较量。]]},["3"]={["id"]=3,["text"]=[[江湖小报：玉螣剑的获取方法为击败守护者，即可拔剑，并不是击杀守护者。]]},["30"]={["id"]=30,["text"]=[[江湖小报：传闻，小猴跳跳公司里是有几个祭坛，专门给技术和策划准备。]]},["31"]={["id"]=31,["text"]=[[江湖小报：基本功法，在一定等级前除了请教于师傅，也可在章节中自行苦练。]]},["32"]={["id"]=32,["text"]=[[江湖小报：10级读书识字等于1点悟性，悟性越高，武学提升所需的潜能就越少。]]},["33"]={["id"]=33,["text"]=[[江湖小报：王维早已富可敌国，熟读四书五经的他却无心继续研读书籍，只想有武艺高强的保镖。]]},["34"]={["id"]=34,["text"]=[[江湖小报：人物评价影响挂机收益比例非常大，想快速升级可尽量的提高人物评价。]]},["35"]={["id"]=35,["text"]=[[江湖小报：目前福缘丹唯一获取途径为江湖名士，一个月江湖名士可领取2颗福缘丹。]]},["36"]={["id"]=36,["text"]=[[江湖小报：江湖名士如卡着730天不动，是因实际天数已超730天，当天数低于730天便恢复。]]},["37"]={["id"]=37,["text"]=[[江湖小报：角色的精力上限和气血上限会随着年龄的增长而提升。]]},["38"]={["id"]=38,["text"]=[[江湖小报：气血上限值主要通过长时间打坐来提升，所以打坐在游戏前期十分重要。]]},["39"]={["id"]=39,["text"]=[[江湖小报：游戏中，鸟类动物最为稀有，却又打之不完。]]},["4"]={["id"]=4,["text"]=[[江湖小报：使用分身符可同时做多件事情，各位大侠若想打坐练功两不误，分身符是个不错的选择。]]},["40"]={["id"]=40,["text"]=[[江湖小报：游戏中，最坚固的土地应当是各门派内大殿，华山村，龙城山庄。]]},["41"]={["id"]=41,["text"]=[[江湖小报：论剑台除了比武，还可以进行观战，也可获取不少收益。]]},["42"]={["id"]=42,["text"]=[[江湖小报：江湖中除了正派、邪派以及中立门派外，还有许多隐世门派，诸多江湖事迹中皆有他们的踪迹。]]},["43"]={["id"]=43,["text"]=[[江湖小报：每日签到活动，每累计30天签到即可获得一个戏曲面具。]]},["44"]={["id"]=44,["text"]=[[江湖小报：自己打造的神兵是可以更换名字的，每次更换需花费200元宝。]]},["45"]={["id"]=45,["text"]=[[江湖小报：黑市商人是最神秘的组织，他们行踪不定且各个身怀异宝，闯荡江湖时遇到他们可不要错过。]]},["46"]={["id"]=46,["text"]=[[江湖小报：门派的基本心法，会增加人物精力上限。]]},["47"]={["id"]=47,["text"]=[[江湖小报：十级基本拳脚可提升一点臂力，臂力越高，进攻时杀伤力将会增强。]]},["48"]={["id"]=48,["text"]=[[江湖小报：十级基本轻功可提升一点身法，身法越高，战斗中将更容易避开对方攻击。]]},["49"]={["id"]=49,["text"]=[[江湖小报：十级基本内功可提升一点根骨，根骨越高，气血恢复将会更快，自身气血也会越多。]]},["5"]={["id"]=5,["text"]=[[江湖小报：如果玩家角色还没有进行过传承，即使打通全部经脉也无法掌握互搏神通。]]},["50"]={["id"]=50,["text"]=[[江湖小报：经脉天赋除了丰富的战斗天赋，还有各类辅助天赋任你选择，还不快去打通经脉？]]},["51"]={["id"]=51,["text"]=[[江湖小报：游戏排行榜会定期重启，届时如果你是第一位登录游戏，众多排行榜榜首必定是你。]]},["52"]={["id"]=52,["text"]=[[江湖小报：排行榜中的佳人榜，除了自身颜值，还有其他数据作为排行名次的依据。]]},["53"]={["id"]=53,["text"]=[[江湖小报：排行榜中的佳人榜，除了自身容貌外，读书和武功也将作为排行名次的依据。]]},["54"]={["id"]=54,["text"]=[[江湖小报：排行榜中的佳人榜，在角色到达一定年龄后，评选时容貌的比重会降低，相应的会提高读书和武功的比重。]]},["55"]={["id"]=55,["text"]=[[江湖小报：醒身丸配合特制檀香使用可以发挥最大效果。]]},["56"]={["id"]=56,["text"]=[[江湖小报：我们一直都在致力的创建一片更大，更辽阔的江湖，也希望每位玩家可文明游戏。]]},["57"]={["id"]=57,["text"]=[[江湖小报：亦正亦邪，何去何从，刀光剑影或是闲鸥野鹭都在你一念之间。]]},["58"]={["id"]=58,["text"]=[[江湖小报：明月照崖人去远，从此无刀也无剑。]]},["59"]={["id"]=59,["text"]=[[江湖小报：当你在特定的地点打开十里香、清风醉以及醉梦生时，会触发各种各样的奇遇事件。]]},["6"]={["id"]=6,["text"]=[[江湖小报：玩家角色传承一次后，打通八条经脉即可获得学习互搏神通的资格。]]},["60"]={["id"]=60,["text"]=[[江湖小报：菩提子使用后会增加角色内力值上限300点，但菩提子的提升传承不保留。]]},["61"]={["id"]=61,["text"]=[[江湖小报：天香玉露使用后会恢复角色50点精力。]]},["62"]={["id"]=62,["text"]=[[江湖小报：流云甘露使用后会恢复角色100点精力。]]},["63"]={["id"]=63,["text"]=[[江湖小报：喝十里香时，可随机获取一个奖励，碎银，潜能，天香玉露。]]},["64"]={["id"]=64,["text"]=[[江湖小报：喝清风醉时，可随机获取一个奖励，碎银，潜能，天香玉露。]]},["65"]={["id"]=65,["text"]=[[江湖小报：拜访任务是福利满满的一个玩法，威望越高，可遇到更好的任务与奖励。]]},["66"]={["id"]=66,["text"]=[[江湖小报：南阳匪乱是每日必做3次的历练任务，收益非常可观。]]},["67"]={["id"]=67,["text"]=[[江湖小报：顾盼间乾坤倒转，一霎时沧海桑田，方晓，弹指红颜老，刹那芳华逝。]]},["68"]={["id"]=68,["text"]=[[江湖小报：只要有人的地方就有恩怨，有恩怨就会有江湖，人就是江湖。]]},["69"]={["id"]=69,["text"]=[[江湖小报：世事难免沧桑，人生难免悲凉。]]},["7"]={["id"]=7,["text"]=[[江湖小报：在设置界面将游戏分享给好友，每日都有元宝领取。]]},["70"]={["id"]=70,["text"]=[[江湖小报：皇图霸业谈笑中，不胜人生一场醉。]]},["71"]={["id"]=71,["text"]=[[江湖小报：天下风云出我辈，一入江湖岁月催。]]},["72"]={["id"]=72,["text"]=[[江湖小报：红颜弹指老，刹那芳华，与其天涯思君，恋恋不舍，莫若相忘于江湖。]]},["73"]={["id"]=73,["text"]=[[江湖小报：论剑每周人气榜，只要人气到达宗师组的要求，最低可获取一瓶醉梦生与两瓶天香玉露。]]},["74"]={["id"]=74,["text"]=[[江湖小报：新注册的角色或刚传承的角色，三天内排行榜信息都不会及时更新。]]},["75"]={["id"]=75,["text"]=[[江湖小报：侠义正气并非任何门派都有需求，如门派无需求可挑选喜欢的称号而努力。]]},["76"]={["id"]=76,["text"]=[[江湖小报：每次传承均会获得一定数量的先天属性点。]]},["77"]={["id"]=77,["text"]=[[江湖小报：通关主线剧情只是游戏的开始，在江湖章节中还有许许多多的故事等着你去经历。]]},["78"]={["id"]=78,["text"]=[[江湖小报：虽然蓬莱岛上侍奉岛主的仆人是戴罪之身，但他的身手依然深不可测。]]},["79"]={["id"]=79,["text"]=[[江湖小报：最新的神兵玩法，最低要求是通关唐门章节关卡才能开启。]]},["8"]={["id"]=8,["text"]=[[江湖小报：制作组彩蛋玩法除了可以获取特殊面具，还可以和策划、程序等亲密接触。]]},["80"]={["id"]=80,["text"]=[[江湖小报：唐门之乱究竟为什么发生？唐不平以前究竟发生了什么？公众号小说了解下？]]},["81"]={["id"]=81,["text"]=[[江湖小报：有名字的NPC，大多数都是有故事背景的。]]},["82"]={["id"]=82,["text"]=[[江湖小报：少侠数没数过春在楼到底有几家分店？]]},["83"]={["id"]=83,["text"]=[[江湖小报：客服小姐姐们曾经包了饺子给大家吃，不过白糖馅的饺子没人敢动。]]},["84"]={["id"]=84,["text"]=[[江湖小报：如果你不小心锤死了重要NPC，不要惊慌，可以等待副本刷新后再来。]]},["85"]={["id"]=85,["text"]=[[江湖小报：春分属于二十四节气，这天人们会踏青，放风筝，采野菜，带簪花。]]},["86"]={["id"]=86,["text"]=[[江湖小报：冬至属于二十四节气，南北习俗不同，会有吃饺子、汤圆、羊肉汤的不同习俗。]]},["87"]={["id"]=87,["text"]=[[江湖小报：黑白无常是本土鬼差，牛头马面则是从天竺（今印度）发源过来。]]},["88"]={["id"]=88,["text"]=[[江湖小报：上厕所的时候裤带一定要拉紧，说不定黑商就在这里悄悄窥视。]]},["89"]={["id"]=89,["text"]=[[江湖小报：制作组的成员平时也会在正式服玩耍，不过他们大多很菜，排名9999＋的那种。]]},["9"]={["id"]=9,["text"]=[[江湖小报：酆都玩法进入时间是固定在晚上八点至凌晨五点，过时不候。]]},["90"]={["id"]=90,["text"]=[[江湖小报：邪派干的不一定就是坏事儿，正派也不都是大侠。]]},["91"]={["id"]=91,["text"]=[[江湖小报：小道消息称，落月山庄隐藏着关系着朝廷的重大秘密。]]}},["Sheet2"]={},["Sheet3"]={}}000